            st[i%5][i//5]^=lane
        keccak_f(st)
    out=b''
    for i in range(4):
        out+=st[i%5][i//5].to_bytes(8,'little')
    return out

if __name__=='__main__':
    for a in sys.argv[1:]:
        print(a, '->', keccak256(a.encode()).hex())
