{"command": "cat > /tmp/enc.py <<'EOF'
import sys
def word(v):
    if isinstance(v,int):
        return v.to_bytes(32,'big').hex()
    return v.rjust(64,'0') if len(v)<=64 else v
def head_len(t):
    return 32 if is_dyn(t) else 0
def is_dyn(t):
    # ethabi-ish
    if t.endswith('[]') or t in ('string','bytes'): return True
    if t.startswith('tuple'): return True
    return False
def enc(types, vals):
    # naive: types list, vals list
    heads=[]; tails=[]
    tail_off = 32*len(types)
    for t,v in zip(types,vals):
        if t=='uint256':
            heads.append(word(int(v,0)))
        elif t in ('string','bytes'):
            b = v.encode() if t=='string' else bytes.fromhex(v)
            pad=(-len(b))%32
            heads.append(word(tail_off+len(tails)*32))
            tails.append(word(len(b))+(b+bytes(pad)).hex())
        elif t=='uint256[]':
            elems=[int(x,0) for x in v.split(',')]
            data=word(len(elems))+''.join(word(e) for e in elems)
            heads.append(word(tail_off+len(tails)*32))
            tails.append(data)
    return ''.join(heads)+''.join(tails)
if __name__=='__main__':
    t=sys.argv[1].split(','); v=sys.argv[2].split('|')
