```
fn parse(s: &str) -> Result<ParamType> {
    // 1. Array suffixes (outermost first)
    if s.ends_with("[]") { return Ok(Array(parse(&s[..s.len()-2])?)) }
    if let Some(idx) = s.rfind('[') {  // for "[n]" suffix
        if s.ends_with(']') && idx < s.len()-1 {
            let inner = parse(&s[..idx])?;
            let len = s[idx+1..s.len()-1].parse::<usize>()?;   // ParseIntError
            return Ok(FixedArray(inner, len))
        }
    }
    // 2. Tuples
    if let Some(l) = s.find('(') {
        if let Some(r) = s.rfind(')') {
            if l < r {
