        return ('fixed', parse(t[:i]), int(t[i+1:-1]))
    return ('base', t)
def enc_head_size(types):
    s=0
    for t in types:
        s += 32 if is_dynamic(t) else static_size(t)
    return s
def static_size(t):
    return 32
def encode_values(types, vals, base=0):
    """returns (head_hex, tail_hex) with offsets relative to base"""
    heads=[]; tails=[]; tail_start=base+enc_head_size(types)
    for t,v in zip(types,vals):
        if is_dynamic(t):
            data=encode_single(t,v)
            heads.append(('%x'%(tail_start+len(tails))).rjust(64,'0'))
            tails.append(data)
        else:
