    if t=='bool': return ('1' if v else '0').rjust(64,'0')
    if t.startswith('bytes') and t[5:].isdigit():
        n=int(t[5:]); b=bytes.fromhex(v); b=b.ljust(n,b'\0'); return b.hex().rjust(64,'0')
    if t=='bytes32': return v.rjust(64,'0')
    raise Exception('unknown static '+t)
def encode_single(t,v):
    p=parse(t)
    if p[0]=='base':
