    pub fn is_zero(&self) -> bool {
        self.0.iter().all(|&x| x == 0)
    }

    pub fn from_be_bytes(bytes: &[u8]) -> Self {
        let mut limbs = [0u64; 4];
        let n = bytes.len();
        // big endian: last byte is the least significant
        for (i, b) in bytes.iter().enumerate() {
            let limb = (n - 1 - i) / 8;
            let byte_idx = (n - 1 - i) % 8;
            limbs[limb] |= (*b as u64) << (byte_idx * 8);
        }
        U256(limbs)
    }

    pub fn to_be_bytes(&self) -> [u8; 32] {
        let mut out = [0u8; 32];
        for i in 0..4 {
            let v = self.0[i];
            for j in 0..8 {
                out[31 - i * 8 - j] = (v >> (j * 8)) as u8;
            }
        }
        out
    }

    pub fn from_dec_str(s: &str) -> Result<Self, DecErr> {
        if s.is_empty() {
            return Ok(U256::zero());
        }
        let mut limbs = [0u64; 4];
        let mut overflow = false;
        for c in s.chars() {
            if !c.is_ascii_digit() {
                return Err(DecErr::InvalidCharacter);
            }
            let d = (c as u8 - b'0') as u64;
            if mul_add_u64(&mut limbs, 10, d) {
                overflow = true;
            }
        }
        if overflow {
            return Err(DecErr::InvalidLength);
        }
        Ok(U256(limbs))
    }

    pub fn to_hex(&self) -> String {
        // lowercase hex without leading zeros, "0" when zero
        let bytes = self.to_be_bytes();
        let mut s = String::new();
        let mut started = false;
        for b in bytes.iter() {
            if !started {
                if *b == 0 {
                    continue;
                }
                started = true;
                if *b < 16 {
                    s.push_str(&format!("{:x}", *b));
                    continue;
                }
                s.push_str(&format!("{:02x}", *b));
                continue;
            }
            s.push_str(&format!("{:02x}", *b));
        }
        if !started {
            s.push('0');
        }
        s
    }

    pub fn cmp(&self, other: &U256) -> std::cmp::Ordering {
        for i in (0..4).rev() {
            if self.0[i] != other.0[i] {
                return self.0[i].cmp(&other.0[i]);
            }
        }
        std::cmp::Ordering::Equal
    }

    pub fn wrapping_neg(&self) -> U256 {
        // two's complement negation
        let mut inv = U256([!self.0[0], !self.0[1], !self.0[2], !self.0[3]]);
        add_one(&mut inv.0);
        inv
    }

    pub fn bit255(&self) -> bool {
        // >= 2^255
        self.0[3] >= 0x8000000000000000u64
    }

    pub fn gt_eq_pow255(&self) -> bool {
        self.0[3] >= 0x8000000000000000u64
    }
}

fn add_one(l: &mut [u64; 4]) -> bool {
    for i in 0..4 {
        let (r, o) = l[i].overflowing_add(1);
        l[i] = r;
        if !o {
            return false;
        }
    }
    true
}
