{"command": "cd /workspace && cat > src/json.rs <<'RSEOF'
//! JSON reader producing a position-annotated tree, with error messages and
//! positions matching serde_json's behaviour for this ABI use-case.

#[derive(Clone, Debug, PartialEq)]
pub enum Num {
    U(u64),
    I(i64),
    F(f64),
}

#[derive(Clone, Debug)]
pub enum Val {
    Null,
    Bool(bool),
    Num(Num),
    Str(String),
    Arr(Vec<Node>),
    Obj(Vec<(Node, Node)>),
}

#[derive(Clone, Debug)]
pub struct Node {
    pub start: usize,
    pub end: usize,
    pub val: Val,
}

#[derive(Debug, Clone)]
pub struct JErr {
    pub msg: String,
    pub line: usize,
    pub column: usize,
}

impl JErr {
    pub fn to_string(&self) -> String {
        format!("{} at line {} column {}", self.msg, self.line, self.column)
    }
}

pub struct Reader<'a> {
    pub s: &'a [u8],
    pub i: usize,
}

impl<'a> Reader<'a> {
    pub fn new(s: &'a [u8]) -> Self {
        Reader { s, i: 0 }
    }

    pub fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }

    pub fn eat(&mut self) -> Option<u8> {
        let c = self.s.get(self.i).copied();
        if c.is_some() {
            self.i += 1;
        }
        c
    }

    pub fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\n' || c == b'\t' || c == b'\r' {
                self.i += 1;
            } else {
                break;
            }
        }
    }

    /// position at current index (number of consumed bytes)
    pub fn position(&self) -> (usize, usize) {
        pos_of_index(self.s, self.i)
    }

    pub fn peek_position(&self) -> (usize, usize) {
        pos_of_index(self.s, usize::min(self.s.len(), self.i + 1))
    }

    pub fn err(&self, msg: &str) -> JErr {
        let (l, c) = self.position();
        JErr { msg: msg.to_string(), line: l, column: c }
    }

    pub fn peek_err(&self, msg: &str) -> JErr {
        let (l, c) = self.peek_position();
        JErr { msg: msg.to_string(), line: l, column: c }
    }

    pub fn err_at(&self, msg: &str, idx: usize) -> JErr {
        let (l, c) = pos_of_index(self.s, idx);
        JErr { msg: msg.to_string(), line: l, column: c }
    }
}

pub fn pos_of_index(s: &[u8], i: usize) -> (usize, usize) {
    let i = usize::min(i, s.len());
    let mut line = 1;
    let mut start_of_line = 0;
    for (k, &b) in s[..i].iter().enumerate() {
        if b == b'\n' {
            line += 1;
            start_of_line = k + 1;
        }
    }
    (line, i - start_of_line)
}

pub fn parse(s: &[u8]) -> Result<Node, JErr> {
    let mut r = Reader::new(s);
    r.skip_ws();
    let node = parse_value(&mut r)?;
    r.skip_ws();
    if r.i < s.len() {
        return Err(r.peek_err("trailing characters"));
    }
    Ok(node)
}

fn parse_value(r: &mut Reader) -> Result<Node, JErr> {
    let start = r.i;
    let peek = match r.peek() {
        Some(b) => b,
        None => return Err(r.peek_err("EOF while parsing a value")),
    };
    let val = match peek {
        b'n' => {
            r.eat();
            parse_ident(r, b"ull")?;
            Val::Null
        }
        b't' => {
            r.eat();
            parse_ident(r, b"rue")?;
            Val::Bool(true)
        }
        b'f' => {
            r.eat();
            parse_ident(r, b"alse")?;
            Val::Bool(false)
        }
        b'"' => {
            let s = parse_string(r)?;
            Val::Str(s)
        }
        b'[' => {
            r.eat();
            let mut items = Vec::new();
            r.skip_ws();
            if r.peek() == Some(b']') {
                r.eat();
                return Ok(Node { start, end: r.i, val: Val::Arr(items) });
            }
            let mut first = true;
            loop {
                r.skip_ws();
                if !first {
                    // expect , or ]
                    match r.peek() {
                        Some(b',') => {
                            r.eat();
                            r.skip_ws();
                            if r.peek() == Some(b']') {
                                return Err(r.peek_err("trailing comma"));
                            }
                        }
                        Some(b']') => {
                            r.eat();
                            break;
                        }
                        Some(_) => return Err(r.peek_err("expected `,` or `]`")),
                        None => return Err(r.peek_err("EOF while parsing a list")),
                    }
                } else {
                    first = false;
                    match r.peek() {
                        Some(b']') => {
                            r.eat();
                            break;
                        }
                        Some(_) => {}
                        None => return Err(r.peek_err("EOF while parsing a list")),
                    }
                }
                let v = parse_value(r)?;
                items.push(v);
            }
            Val::Arr(items)
        }
        b'{' => {
            r.eat();
            let mut items: Vec<(Node, Node)> = Vec::new();
            r.skip_ws();
            if r.peek() == Some(b'}') {
                r.eat();
                return Ok(Node { start, end: r.i, val: Val::Obj(items) });
            }
            let mut first = true;
            loop {
                r.skip_ws();
                if !first {
                    match r.peek() {
                        Some(b',') => {
                            r.eat();
                            r.skip_ws();
                            if r.peek() == Some(b'}') {
                                return Err(r.peek_err("trailing comma"));
                            }
                        }
                        Some(b'}') => {
                            r.eat();
                            break;
                        }
                        Some(_) => return Err(r.peek_err("expected `,` or `}`")),
                        None => return Err(r.peek_err("EOF while parsing an object")),
                    }
                } else {
                    first = false;
                }
                // key
                match r.peek() {
                    Some(b'"') => {}
                    Some(_) => return Err(r.peek_err("key must be a string")),
                    None => return Err(r.peek_err("EOF while parsing an object")),
                }
                let kstart = r.i;
                let ks = parse_string(r)?;
                let kend = r.i;
                r.skip_ws();
                match r.peek() {
                    Some(b':') => {
                        r.eat();
                    }
                    Some(_) => return Err(r.peek_err("expected `:`")),
                    None => return Err(r.peek_err("EOF while parsing an object")),
                }
                r.skip_ws();
                let v = parse_value(r)?;
                items.push((
                    Node { start: kstart, end: kend, val: Val::Str(ks) },
                    v,
                ));
            }
            Val::Obj(items)
        }
        b'-' => {
            r.eat();
            parse_number(r, start, false)?
        }
        b'0'..=b'9' => parse_number(r, start, true)?,
        _ => {
            return Err(r.peek_err("expected value"));
        }
    };
    Ok(Node { start, end: r.i, val })
}

fn parse_ident(r: &mut Reader, expect: &[u8]) -> Result<(), JErr> {
    for &e in expect {
        match r.peek() {
            Some(c) if c == e => {
                r.i += 1;
            }
            Some(_) => return Err(r.peek_err("expected ident")),
            None => return Err(r.peek_err("EOF while parsing a value")),
        }
    }
    Ok(())
}

fn parse_string(r: &mut Reader) -> Result<String, JErr> {
    // assumes the leading quote is present
    r.i += 1; // opening quote
    let mut out: Vec<u8> = Vec::new();
    loop {
        let start = r.i;
        while let Some(c) = r.peek() {
            if c == b'"' || c == b'\\' || c < 0x20 {
                break;
            }
            r.i += 1;
        }
        out.extend_from_slice(&r.s[start..r.i]);
        match r.peek() {
            None => return Err(r.peek_err("EOF while parsing a string")),
            Some(b'"') => {
                // validate utf8
                match std::str::from_utf8(&out) {
                    Ok(s) => {
                        r.i += 1;
                        return Ok(s.to_string());
                    }
                    Err(_) => {
                        r.i += 1;
                        return Err(r.err("invalid unicode code point"));
                    }
                }
            }
            Some(b'\\') => {
                r.i += 1;
                let c = match r.peek() {
                    Some(c) => c,
                    None => return Err(r.peek_err("EOF while parsing a string")),
                };
                r.i += 1;
                match c {
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'b' => out.push(0x08),
                    b'f' => out.push(0x0c),
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
                    b'u' => {
                        let cp = decode_hex_escape(r)?;
                        if (0xD800..0xDC00).contains(&cp) {
                            // lone leading surrogate
                            if r.peek() == Some(b'\\') {
                                r.i += 1;
                                if r.peek() == Some(b'u') {
                                    r.i += 1;
                                    let cp2 = decode_hex_escape(r)?;
                                    if (0xDC00..0xE000).contains(&cp2) {
                                        let c = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                        push_utf8(&mut out, c as u32);
                                        continue;
                                    }
                                }
                            }
                            return Err(r.err("lone leading surrogate in hex escape"));
                        }
                        if (0xDC00..0xE000).contains(&cp) {
                            return Err(r.err("unexpected end of hex escape"));
                        }
                        push_utf8(&mut out, cp as u32);
                    }
                    _ => return Err(r.err("invalid escape")),
                }
            }
            Some(_) => {
                r.i += 1;
                return Err(r.err("control character (\\u0000-\\u001F) found while parsing a string"));
            }
        }
    }
}

fn push_utf8(out: &mut Vec<u8>, c: u32) {
    let ch = char::from_u32(c).unwrap_or('\u{fffd}');
    let mut buf = [0u8; 4];
    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
}

fn decode_hex_escape(r: &mut Reader) -> Result<u16, JErr> {
    let mut n: u16 = 0;
    for _ in 0..4 {
        let c = match r.peek() {
            Some(c) => c,
            None => return Err(r.peek_err("EOF while parsing a string")),
        };
        let d = match c {
            b'0'..=b'9' => (c - b'0') as u16,
            b'a'..=b'f' => (c - b'a' + 10) as u16,
            b'A'..=b'F' => (c - b'A' + 10) as u16,
            _ => return Err(r.peek_err("invalid escape")),
        };
        r.i += 1;
        n = n * 16 + d;
    }
    Ok(n)
}

fn parse_number(r: &mut Reader, start: usize, positive: bool) -> Result<Val, JErr> {
    let s = &r.s[start..];
    let mut i = 0usize;
    if !positive {
        i += 1; // '-'
    }
    // integer part
    if i >= s.len() || !s[i].is_ascii_digit() {
        return Err(r.err_at("invalid number", usize::min(s.len(), start + i + 1)));
    }
    if s[i] == b'0' {
        i += 1;
        if i < s.len() && s[i].is_ascii_digit() {
            return Err(r.err_at("invalid number", usize::min(s.len(), start + i + 1)));
        }
    } else {
        while i < s.len() && s[i].is_ascii_digit() {
            i += 1;
        }
    }
    let mut is_float = false;
    if i < s.len() && s[i] == b'.' {
        is_float = true;
        i += 1;
        if i >= s.len() || !s[i].is_ascii_digit() {
            return Err(r.err_at("invalid number", usize::min(s.len(), start + i + 1)));
        }
        while i < s.len() && s[i].is_ascii_digit() {
            i += 1;
        }
    }
    if i < s.len() && (s[i] == b'e' || s[i] == b'E') {
        is_float = true;
        i += 1;
        if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
            i += 1;
        }
        if i >= s.len() || !s[i].is_ascii_digit() {
            return Err(r.err_at("invalid number", usize::min(s.len(), start + i + 1)));
        }
        while i < s.len() && s[i].is_ascii_digit() {
            i += 1;
        }
    }
    let text = std::str::from_utf8(&s[..i]).unwrap();
    if is_float {
        let f: f64 = text.parse().unwrap_or(f64::INFINITY);
        if !f.is_finite() {
            return Err(r.err_at("number out of range", usize::min(s.len(), start + i + 1)));
        }
        r.i = start + i;
        return Ok(Val::Num(Num::F(f)));
    }
    if positive {
        match text.parse::<u64>() {
            Ok(v) => {
                r.i = start + i;
                return Ok(Val::Num(Num::U(v)));
            }
            Err(_) => {}
        }
    } else {
        match text.parse::<i64>() {
            Ok(v) => {
                r.i = start + i;
                return Ok(Val::Num(Num::I(v)));
            }
            Err(_) => {}
        }
    }
    // fall back to float
    let f: f64 = text.parse().unwrap_or(f64::INFINITY);
    if !f.is_finite() {
        return Err(r.err_at("number out of range", usize::min(s.len(), start + i + 1)));
    }
    r.i = start + i;
    Ok(Val::Num(Num::F(f)))
}

pub fn unexpected_desc(n: &Node) -> String {
    match &n.val {
        Val::Null => "null".to_string(),
        Val::Bool(b) => format!("boolean `{}`", b),
        Val::Num(Num::U(v)) => format!("integer `{}`", v),
        Val::Num(Num::I(v)) => format!("integer `{}`", v),
        Val::Num(Num::F(f)) => format!("floating point `{}`", fmt_f64(*f)),
        Val::Str(s) => format!("string {:?}", s),
        Val::Arr(_) => "sequence".to_string(),
        Val::Obj(_) => "map".to_string(),
    }
}

/// ryu-like shortest float formatting used by serde's error messages.
pub fn fmt_f64(v: f64) -> String {
    if v == 0.0 {
        if v.is_sign_negative() {
            return "-0.0".to_string();
        }
        return "0.0".to_string();
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }
    let neg = v < 0.0;
    let a = v.abs();
    let disp = format!("{}", a);
    let (int_part, frac_part) = match disp.split_once('.') {
        Some((a, b)) => (a.to_string(), b.to_string()),
        None => (disp.clone(), String::new()),
    };
    let e: i32 = if int_part != "0" {
        int_part.len() as i32 - 1
    } else {
        let nz = frac_part.chars().position(|c| c != '0').map(|i| i as i32).unwrap_or(0);
        -(nz + 1)
    };
    let digits: String = format!("{}{}", int_part, frac_part)
        .trim_start_matches('0')
        .trim_end_matches('0')
        .to_string();
    let digits = if digits.is_empty() { "0".to_string() } else { digits };
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if e >= 16 || e < -5 {
        // exponent notation
        out.push_str(&digits[0..1]);
        if digits.len() > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        if e >= 0 {
            out.push('+');
        }
        out.push_str(&e.to_string());
    } else if e >= 0 {
        let ip_len = (e + 1) as usize;
        let d = digits.clone();
        if ip_len >= d.len() {
            out.push_str(&d);
            for _ in 0..(ip_len - d.len()) {
                out.push('0');
            }
            out.push_str(".0");
        } else {
            out.push_str(&d[..ip_len]);
            out.push('.');
            out.push_str(&d[ip_len..]);
        }
    } else {
        out.push_str("0.");
        for _ in 0..(-e - 1) {
            out.push('0');
        }
        out.push_str(&digits);
    }
    out
}
