                };
                r.i += 1;
                match c {
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'b' => out.push(0x08),
                    b'f' => out.push(0x0c),
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
                    b'u' => {
                        let cp = decode_hex_escape(r)?;
                        if (0xD800..0xDC00).contains(&cp) {
                            // lone leading surrogate
                            if r.peek() == Some(b'\\') {
                                r.i += 1;
                                if r.peek() == Some(b'u') {
                                    r.i += 1;
                                    let cp2 = decode_hex_escape(r)?;
                                    if (0xDC00..0xE000).contains(&cp2) {
                                        let c = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                        push_utf8(&mut out, c as u32);
                                        continue;
                                    }
                                }
                            }
                            return Err(r.err("lone leading surrogate in hex escape"));
                        }
                        if (0xDC00..0xE000).contains(&cp) {
                            return Err(r.err("unexpected end of hex escape"));
                        }
                        push_utf8(&mut out, cp as u32);
                    }
                    _ => return Err(r.err("invalid escape")),
                }
            }
            Some(_) => {
                r.i += 1;
                return Err(r.err("control character (\\u0000-\\u001F) found while parsing a string"));
            }
        }
    }
}

fn push_utf8(out: &mut Vec<u8>, c: u32) {
