//! JSON reader producing a position-annotated tree, with error messages and
//! positions matching serde_json's behaviour for this ABI use-case.

#[derive(Clone, Debug, PartialEq)]
pub enum Num {
    U(u64),
    I(i64),
    F(f64),
}

#[derive(Clone, Debug)]
pub enum Val {
    Null,
    Bool(bool),
    Num(Num),
    Str(String),
    Arr(Vec<Node>),
    Obj(Vec<(Node, Node)>),
}

#[derive(Clone, Debug)]
pub struct Node {
    pub start: usize,
    pub end: usize,
    pub val: Val,
}

#[derive(Debug, Clone)]
pub struct JErr {
    pub msg: String,
    pub line: usize,
    pub column: usize,
}

impl JErr {
    pub fn to_string(&self) -> String {
        format!("{} at line {} column {}", self.msg, self.line, self.column)
    }
}

pub struct Reader<'a> {
    pub s: &'a [u8],
    pub i: usize,
}

impl<'a> Reader<'a> {
    pub fn new(s: &'a [u8]) -> Self {
        Reader { s, i: 0 }
    }

    pub fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }

    pub fn eat(&mut self) -> Option<u8> {
        let c = self.s.get(self.i).copied();
        if c.is_some() {
            self.i += 1;
        }
        c
    }

    pub fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\n' || c == b'\t' || c == b'\r' {
                self.i += 1;
            } else {
                break;
            }
        }
    }

    /// position at current index (number of consumed bytes)
    pub fn position(&self) -> (usize, usize) {
        pos_of_index(self.s, self.i)
    }

    pub fn peek_position(&self) -> (usize, usize) {
        pos_of_index(self.s, usize::min(self.s.len(), self.i + 1))
    }

    pub fn err(&self, msg: &str) -> JErr {
        let (l, c) = self.position();
        JErr { msg: msg.to_string(), line: l, column: c }
    }

    pub fn peek_err(&self, msg: &str) -> JErr {
        let (l, c) = self.peek_position();
        JErr { msg: msg.to_string(), line: l, column: c }
    }

    pub fn err_at(&self, msg: &str, idx: usize) -> JErr {
        let (l, c) = pos_of_index(self.s, idx);
        JErr { msg: msg.to_string(), line: l, column: c }
    }
}

pub fn pos_of_index(s: &[u8], i: usize) -> (usize, usize) {
    let i = usize::min(i, s.len());
    let mut line = 1;
    let mut start_of_line = 0;
    for (k, &b) in s[..i].iter().enumerate() {
        if b == b'\n' {
            line += 1;
            start_of_line = k + 1;
        }
    }
    (line, i - start_of_line)
