//! ABI model: param types, params, functions, events, contract lookup,
//! encoding and decoding.

use crate::keccak::keccak256;
use crate::u256::{DecErr, U256};
use crate::json::{Node, Val, JErr};
use std::collections::HashMap;

pub const LONG_MSG: &str = "please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist";

#[derive(Debug, Clone)]
pub enum EthErr {
    InvalidData,
    Hex(HexErr),
    Uint(DecErr),
    IntOverflow,
    ParseInt(&'static str),
    InvalidName(String),
    Other(String),
    Serialization(String),
    Long,
}

#[derive(Debug, Clone)]
pub enum HexErr {
    OddLength,
    InvalidChar(char, usize),
}

impl HexErr {
    pub fn to_string(&self) -> String {
        match self {
            HexErr::OddLength => "Odd number of digits".to_string(),
            HexErr::InvalidChar(c, i) => format!("Invalid character '{}' at position {}", c, i),
        }
    }
}

impl EthErr {
    pub fn message(&self) -> String {
        match self {
            EthErr::InvalidData => "Invalid data".to_string(),
            EthErr::Hex(e) => format!("Hex parsing error: {}", e.to_string()),
            EthErr::Uint(e) => format!("Uint parse error: {}", e.debug()),
            EthErr::IntOverflow => "int256 parse error: Overflow".to_string(),
            EthErr::ParseInt(e) => format!("Integer parsing error: {}", e),
            EthErr::InvalidName(s) => format!("Invalid name: {}", s),
            EthErr::Other(s) => s.clone(),
            EthErr::Serialization(s) => format!("Serialization error: {}", s),
            EthErr::Long => format!("Invalid name: {}", LONG_MSG),
        }
    }

    /// the "Caused by" line, if any
    pub fn cause(&self) -> Option<String> {
        match self {
            EthErr::Hex(e) => Some(e.to_string()),
            EthErr::Serialization(s) => Some(s.clone()),
            EthErr::ParseInt(e) => Some(e.to_string()),
            _ => None,
        }
    }

    /// serde-style debug rendering used inside deserialization error messages
    pub fn serde_debug(&self) -> String {
        match self {
            EthErr::InvalidData => "InvalidData".to_string(),
            EthErr::Hex(e) => format!("Hex({:?})", e.to_string()),
            EthErr::Uint(e) => format!("Uint({:?})", e.debug()),
            EthErr::IntOverflow => "Int(Overflow)".to_string(),
            EthErr::ParseInt(e) => format!("ParseInt(ParseIntError {{ kind: {} }})", serde_parse_int_kind(e)),
            EthErr::InvalidName(s) => format!("InvalidName({:?})", s),
            EthErr::Other(s) => format!("Other({:?})", s),
            EthErr::Serialization(s) => format!("Serialization({:?})", s),
            EthErr::Long => format!("Other({:?})", LONG_MSG),
        }
    }
}

fn serde_parse_int_kind(e: &&'static str) -> &'static str {
    if *e == "invalid digit found in string" {
        "InvalidDigit"
    } else if *e == "number too large to fit in target type" {
        "PosOverflow"
    } else if *e == "number too small to fit in target type" {
        "NegOverflow"
    } else {
        "Empty"
    }
}

pub fn from_hex(s: &str) -> Result<Vec<u8>, EthErr> {
    let b = s.as_bytes();
    if b.len() % 2 != 0 {
        return Err(EthErr::Hex(HexErr::OddLength));
    }
    let mut out = Vec::with_capacity(b.len() / 2);
    let mut i = 0;
    while i < b.len() {
        let hi = match hex_val(b[i]) {
            Some(v) => v,
            None => return Err(EthErr::Hex(HexErr::InvalidChar(b[i] as char, i))),
        };
        let lo = match hex_val(b[i + 1]) {
            Some(v) => v,
            None => return Err(EthErr::Hex(HexErr::InvalidChar(b[i + 1] as char, i + 1))),
        };
        out.push(hi * 16 + lo);
        i += 2;
    }
    Ok(out)
}

fn hex_val(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

pub fn strip_0x(s: &str) -> &str {
    if s.len() >= 2 && s.as_bytes()[0] == b'0' && s.as_bytes()[1] == b'x' {
        &s[2..]
    } else {
        s
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParamType {
    Address,
    Bytes,
    FixedBytes(usize),
    Int(usize),
    Uint(usize),
    Bool,
    String,
    Array(Box<ParamType>),
    FixedArray(Box<ParamType>, usize),
    Tuple(Vec<ParamType>),
}

fn parse_bits(s: &str) -> Result<usize, EthErr> {
    if s.is_empty() {
        return Ok(256);
    }
    match s.parse::<usize>() {
        Ok(v) => Ok(v),
        Err(_) => {
            if s.chars().all(|c| c.is_ascii_digit()) {
                Err(EthErr::ParseInt("number too large to fit in target type"))
            } else {
                Err(EthErr::ParseInt("invalid digit found in string"))
            }
        }
    }
}

impl ParamType {
    pub fn parse(s: &str) -> Result<ParamType, EthErr> {
        if s.ends_with("[]") {
            let inner = &s[..s.len() - 2];
            return Ok(ParamType::Array(Box::new(ParamType::parse(inner)?)));
        }
        if s.ends_with(']') {
            if let Some(i) = s.rfind('[') {
                let inner = ParamType::parse(&s[..i])?;
                let len = parse_bits(&s[i + 1..s.len() - 1])?;
                return Ok(ParamType::FixedArray(Box::new(inner), len));
            }
        }
        if s.ends_with(')') {
            if let Some(i) = s.find('(') {
                let name = &s[..i];
                if !name.is_empty() {
                    return Err(EthErr::InvalidName(s.to_string()));
                }
                let inner = &s[i + 1..s.len() - 1];
                let mut comps = Vec::new();
                for part in inner.split(',') {
                    comps.push(ParamType::parse(part)?);
                }
                return Ok(ParamType::Tuple(comps));
            }
            return Err(EthErr::InvalidName(s.to_string()));
        }
        match s {
            "address" => return Ok(ParamType::Address),
            "bool" => return Ok(ParamType::Bool),
            "string" => return Ok(ParamType::String),
            _ => {}
        }
        if let Some(rest) = s.strip_prefix("uint") {
            return Ok(ParamType::Uint(parse_bits(rest)?));
        }
        if let Some(rest) = s.strip_prefix("int") {
            return Ok(ParamType::Int(parse_bits(rest)?));
        }
        if let Some(rest) = s.strip_prefix("bytes") {
            if rest.is_empty() {
                return Ok(ParamType::Bytes);
            }
            return Ok(ParamType::FixedBytes(parse_bits(rest)?));
        }
        Ok(ParamType::Uint(8))
    }

    pub fn to_sig(&self) -> String {
        match self {
            ParamType::Address => "address".to_string(),
            ParamType::Bytes => "bytes".to_string(),
            ParamType::FixedBytes(n) => format!("bytes{}", n),
            ParamType::Int(n) => format!("int{}", n),
            ParamType::Uint(n) => format!("uint{}", n),
            ParamType::Bool => "bool".to_string(),
            ParamType::String => "string".to_string(),
            ParamType::Array(t) => format!("{}[]", t.to_sig()),
            ParamType::FixedArray(t, n) => format!("{}[{}]", t.to_sig(), n),
            ParamType::Tuple(ts) => {
                let inner: Vec<String> = ts.iter().map(|t| t.to_sig()).collect();
                format!("({})", inner.join(","))
            }
        }
    }

    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String => true,
            ParamType::Array(_) => true,
            ParamType::FixedArray(t, _) => t.is_dynamic(),
            ParamType::Tuple(ts) => ts.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Param {
    pub name: String,
    pub kind: ParamType,
    pub indexed: bool,
}

#[derive(Debug, Clone)]
pub struct Function {
    pub name: String,
    pub inputs: Vec<Param>,
    pub outputs: Vec<Param>,
}

impl Function {
    pub fn signature(&self) -> String {
        let types: Vec<String> = self.inputs.iter().map(|p| p.kind.to_sig()).collect();
        format!("{}({})", self.name, types.join(","))
    }

    pub fn selector(&self) -> [u8; 4] {
        let h = keccak256(self.signature().as_bytes());
        [h[0], h[1], h[2], h[3]]
    }

    pub fn short_signature(&self) -> String {
        let h = keccak256(self.signature().as_bytes());
        format!("0x{}{}\u{2026}{}{}", hex2(&h[0]), hex2(&h[1]), hex2(&h[30]), hex2(&h[31]))
    }
}

pub fn hex2(b: &u8) -> String {
    format!("{:02x}", b)
}

pub fn short_sig(s: &str) -> String {
    let h = keccak256(s.as_bytes());
    format!("0x{}{}\u{2026}{}{}", hex2(&h[0]), hex2(&h[1]), hex2(&h[30]), hex2(&h[31]))
}

#[derive(Debug, Clone)]
pub struct Event {
    pub name: String,
    pub inputs: Vec<Param>,
    pub anonymous: bool,
}

impl Event {
    pub fn signature(&self) -> String {
        let types: Vec<String> = self.inputs.iter().map(|p| p.kind.to_sig()).collect();
        format!("{}({})", self.name, types.join(","))
    }
}

#[derive(Debug, Clone, Default)]
pub struct Contract {
    pub functions: HashMap<String, Vec<Function>>,
    pub events: HashMap<String, Vec<Event>>,
}

impl Contract {
    pub fn function(&self, fn_str: &str) -> Result<&Function, EthErr> {
        if let Some(i) = fn_str.find('(') {
            let name = &fn_str[..i];
            let fns = match self.functions.get(name) {
                Some(f) => f,
                None => return Err(EthErr::InvalidName(name.to_string())),
            };
            for f in fns.iter() {
                if f.signature() == fn_str && f.outputs.is_empty() {
                    return Ok(f);
                }
            }
            Err(EthErr::Other(format!("invalid function signature `{}`", fn_str)))
        } else {
            let fns = match self.functions.get(fn_str) {
                Some(f) => f,
                None => return Err(EthErr::InvalidName(fn_str.to_string())),
            };
            if fns.len() != 1 {
                return Err(EthErr::Other(format!(
                    "More than one function found for name `{}`, try providing the full signature",
                    fn_str
                )));
            }
            Ok(&fns[0])
        }
    }

    pub fn event(&self, ev_str: &str) -> Result<&Event, EthErr> {
        if let Some(i) = ev_str.find('(') {
            let name = &ev_str[..i];
            let evs = match self.events.get(name) {
                Some(f) => f,
                None => return Err(EthErr::InvalidName(name.to_string())),
            };
            for e in evs.iter() {
                if e.signature() == ev_str {
                    return Ok(e);
                }
            }
            Err(EthErr::Other(format!("Invalid signature `{}`", short_sig(ev_str))))
        } else {
            let evs = match self.events.get(ev_str) {
                Some(f) => f,
                None => return Err(EthErr::InvalidName(ev_str.to_string())),
            };
            if evs.len() != 1 {
                return Err(EthErr::Other(format!(
                    "More than one function found for name `{}`, try providing the full signature",
                    ev_str
                )));
            }
            Ok(&evs[0])
        }
    }
}

// ---------------- tokens ----------------

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Address([u8; 20]),
    Bytes(Vec<u8>),
    FixedBytes(Vec<u8>),
    Int(U256),
    Uint(U256),
    Bool(bool),
    String(String),
    FixedArray(Vec<Token>),
    Array(Vec<Token>),
    Tuple(Vec<Token>),
}

impl Token {
    pub fn display(&self) -> String {
        match self {
            Token::Address(a) => a.iter().map(|b| format!("{:02x}", b)).collect(),
            Token::Bytes(b) => b.iter().map(|x| format!("{:02x}", x)).collect(),
            Token::FixedBytes(b) => b.iter().map(|x| format!("{:02x}", x)).collect(),
            Token::Int(v) => v.to_hex(),
            Token::Uint(v) => v.to_hex(),
            Token::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Token::String(s) => s.clone(),
            Token::FixedArray(ts) | Token::Array(ts) | Token::Tuple(ts) => {
                let inner: Vec<String> = ts.iter().map(|t| t.display()).collect();
                format!("[{}]", inner.join(","))
            }
        }
    }
}

// ---------------- encoding ----------------

pub fn encode_sequence(kinds: &[ParamType], tokens: &[Token]) -> Result<Vec<u8>, EthErr> {
    let mut head: Vec<u8> = Vec::new();
    let mut tail: Vec<u8> = Vec::new();
    let head_len = 32 * kinds.len();
    for (i, k) in kinds.iter().enumerate() {
        let t = &tokens[i];
        if k.is_dynamic() {
            let off = head_len + tail.len();
            head.extend_from_slice(&u256_word(off as u128));
            tail.extend_from_slice(&encode_one(k, t)?);
        } else {
            head.extend_from_slice(&encode_static(k, t)?);
        }
    }
    head.extend_from_slice(&tail);
    Ok(head)
}

fn u256_word(v: u128) -> [u8; 32] {
    let mut out = [0u8; 32];
    out[16..32].copy_from_slice(&v.to_be_bytes());
    out
}

fn encode_static(kind: &ParamType, t: &Token) -> Result<[u8; 32], EthErr> {
    let mut out = [0u8; 32];
    match (kind, t) {
        (ParamType::Address, Token::Address(a)) => out[12..32].copy_from_slice(a),
        (ParamType::FixedBytes(_), Token::FixedBytes(b)) => {
            out[..b.len()].copy_from_slice(b);
        }
        (ParamType::Int(_), Token::Int(v)) | (ParamType::Uint(_), Token::Uint(v)) => {
            out.copy_from_slice(&v.to_be_bytes());
        }
        (ParamType::Bool, Token::Bool(b)) => {
            if *b {
                out[31] = 1;
            }
        }
        _ => return Err(EthErr::InvalidData),
    }
    Ok(out)
}

fn encode_one(kind: &ParamType, t: &Token) -> Result<Vec<u8>, EthErr> {
    match (kind, t) {
        (ParamType::Bytes, Token::Bytes(b)) => {
            let mut out = u256_word(b.len() as u128).to_vec();
            let padded = pad32(b);
            out.extend_from_slice(&padded);
            Ok(out)
        }
        (ParamType::String, Token::String(s)) => {
            let b = s.as_bytes();
            let mut out = u256_word(b.len() as u128).to_vec();
            out.extend_from_slice(&pad32(b));
            Ok(out)
        }
        (ParamType::Array(inner), Token::Array(ts)) => {
            let kinds: Vec<ParamType> = (0..ts.len()).map(|_| (**inner).clone()).collect();
            let body = encode_sequence(&kinds, ts)?;
            let mut out = u256_word(ts.len() as u128).to_vec();
            out.extend_from_slice(&body);
            Ok(out)
        }
        (ParamType::FixedArray(inner, n), Token::FixedArray(ts)) => {
            if ts.len() != *n {
                return Err(EthErr::InvalidData);
            }
            let kinds: Vec<ParamType> = (0..*n).map(|_| (**inner).clone()).collect();
            encode_sequence(&kinds, ts)
        }
        (ParamType::Tuple(inner), Token::Tuple(ts)) => {
            if ts.len() != inner.len() {
                return Err(EthErr::InvalidData);
            }
            encode_sequence(inner, ts)
        }
        _ => {
            // static types can be encoded in place
            let w = encode_static(kind, t)?;
            Ok(w.to_vec())
        }
    }
}

fn pad32(b: &[u8]) -> Vec<u8> {
    let mut out = b.to_vec();
    while out.len() % 32 != 0 {
        out.push(0);
    }
    out
}

// ---------------- parsing params from the CLI ----------------

pub fn parse_token(kind: &ParamType, params: &[&str], lenient: bool) -> Result<Token, EthErr> {
    let value = match params.first() {
        Some(v) => *v,
        None => return Err(EthErr::InvalidData),
    };
    match kind {
        ParamType::Address => {
            let b = from_hex(strip_0x(value))?;
            if b.len() != 20 {
                return Err(EthErr::InvalidData);
            }
            let mut a = [0u8; 20];
            a.copy_from_slice(&b);
            Ok(Token::Address(a))
        }
        ParamType::Bytes => {
            let b = from_hex(strip_0x(value))?;
            Ok(Token::Bytes(b))
        }
        ParamType::FixedBytes(n) => {
            let b = from_hex(strip_0x(value))?;
            if b.len() != *n {
                return Err(EthErr::InvalidData);
            }
            Ok(Token::FixedBytes(b))
        }
        ParamType::Uint(_) => {
            let v = if lenient {
                U256::from_dec_str(value).map_err(EthErr::Uint)?
            } else {
                let b = from_hex(value)?;
                if b.len() != 32 {
                    return Err(EthErr::InvalidData);
                }
                U256::from_be_bytes(&b)
            };
            Ok(Token::Uint(v))
        }
        ParamType::Int(_) => {
            let v = if lenient {
                let (neg, mag) = if let Some(rest) = value.strip_prefix('-') {
                    (true, rest)
                } else {
                    (false, value)
                };
                let m = U256::from_dec_str(mag).map_err(EthErr::Uint)?;
                if neg {
                    if m.cmp(&u256_pow255()) == std::cmp::Ordering::Greater {
                        return Err(EthErr::IntOverflow);
                    }
                    m.wrapping_neg()
                } else {
                    if m.gt_eq_pow255() {
                        return Err(EthErr::IntOverflow);
                    }
                    m
                }
            } else {
                let b = from_hex(value)?;
                if b.len() != 32 {
                    return Err(EthErr::InvalidData);
                }
                U256::from_be_bytes(&b)
            };
            Ok(Token::Int(v))
        }
        ParamType::Bool => {
            match value {
                "true" | "1" => Ok(Token::Bool(true)),
                "false" | "0" => Ok(Token::Bool(false)),
                _ => Err(EthErr::InvalidData),
            }
        }
        ParamType::String => Ok(Token::String(value.to_string())),
        ParamType::Array(_) | ParamType::FixedArray(_, _) | ParamType::Tuple(_) => {
            Err(EthErr::InvalidData)
        }
    }
}

fn u256_pow255() -> U256 {
    let mut v = [0u64; 4];
    v[3] = 0x8000000000000000u64;
    U256(v)
}

// ---------------- decoding ----------------

pub fn decode_types(kinds: &[ParamType], data: &[u8]) -> Result<Vec<Token>, EthErr> {
    if data.is_empty() && !kinds.is_empty() {
        return Err(EthErr::Long);
    }
    let head_len = 32 * kinds.len();
    if data.len() < head_len {
        return Err(EthErr::InvalidData);
    }
    let mut out = Vec::new();
    let mut tail_start = head_len;
    let mut tail: Vec<(usize, &ParamType)> = Vec::new();
    for (i, k) in kinds.iter().enumerate() {
        let w = 32 * i;
        if k.is_dynamic() {
            let off = word_to_usize(&data[w..w + 32])?;
            tail.push((off, k));
        } else {
            out.push(decode_static(k, &data[w..w + 32])?);
        }
    }
    let _ = tail_start;
    for (off, k) in tail {
        if off > data.len() {
            return Err(EthErr::InvalidData);
        }
        let t = decode_one(k, &data[off..])?;
        out.push(t);
    }
    Ok(out)
}

fn word_to_usize(b: &[u8]) -> Result<usize, EthErr> {
    let v = U256::from_be_bytes(b);
    // must fit in usize
    let bytes = v.to_be_bytes();
    for i in 0..24 {
        if bytes[i] != 0 {
            return Err(EthErr::InvalidData);
        }
    }
    let mut n: usize = 0;
    for i in 24..32 {
        n = (n << 8) | bytes[i] as usize;
    }
    Ok(n)
}

fn decode_static(kind: &ParamType, w: &[u8]) -> Result<Token, EthErr> {
    if w.len() < 32 {
        return Err(EthErr::InvalidData);
    }
    match kind {
        ParamType::Address => {
            let mut a = [0u8; 20];
            a.copy_from_slice(&w[12..32]);
            Ok(Token::Address(a))
        }
        ParamType::FixedBytes(n) => Ok(Token::FixedBytes(w[..*n].to_vec())),
        ParamType::Int(_) => Ok(Token::Int(U256::from_be_bytes(w))),
        ParamType::Uint(_) => Ok(Token::Uint(U256::from_be_bytes(w))),
        ParamType::Bool => Ok(Token::Bool(w[31] == 1)),
        _ => Err(EthErr::InvalidData),
    }
}

fn decode_one(kind: &ParamType, data: &[u8]) -> Result<Token, EthErr> {
    if data.is_empty() {
        return Err(EthErr::Long);
    }
    match kind {
        ParamType::Bytes | ParamType::String => {
            if data.len() < 32 {
                return Err(EthErr::InvalidData);
            }
            let len = word_to_usize(&data[..32])?;
            if data.len() < 32 + len {
                return Err(EthErr::InvalidData);
            }
            let b = data[32..32 + len].to_vec();
            if *kind == ParamType::String {
                match String::from_utf8(b) {
                    Ok(s) => Ok(Token::String(s)),
                    Err(_) => Ok(Token::String(String::from_utf8_lossy(&b).to_string())),
                }
            } else {
                Ok(Token::Bytes(b))
            }
        }
        ParamType::Array(inner) => {
            if data.len() < 32 {
                return Err(EthErr::InvalidData);
            }
            let len = word_to_usize(&data[..32])?;
            let kinds: Vec<ParamType> = (0..len).map(|_| (**inner).clone()).collect();
            let ts = decode_types(&kinds, &data[32..])?;
            Ok(Token::Array(ts))
        }
        ParamType::FixedArray(inner, n) => {
            let kinds: Vec<ParamType> = (0..*n).map(|_| (**inner).clone()).collect();
            let ts = decode_types(&kinds, data)?;
            Ok(Token::FixedArray(ts))
        }
        ParamType::Tuple(inner) => {
            let ts = decode_types(inner, data)?;
            Ok(Token::Tuple(ts))
        }
        _ => decode_static(kind, data),
    }
}

// ---------------- log decoding ----------------

pub fn word_to_token(kind: &ParamType, w: &[u8]) -> Result<Token, EthErr> {
    if w.len() != 32 {
        return Err(EthErr::Other("Invalid input length".to_string()));
    }
    match kind {
        ParamType::Address => {
            let mut a = [0u8; 20];
            a.copy_from_slice(&w[12..32]);
            Ok(Token::Address(a))
        }
        ParamType::FixedBytes(n) => Ok(Token::FixedBytes(w[..*n].to_vec())),
        ParamType::Int(_) => Ok(Token::Int(U256::from_be_bytes(w))),
        ParamType::Uint(_) => Ok(Token::Uint(U256::from_be_bytes(w))),
        ParamType::Bool => Ok(Token::Bool(w[31] == 1)),
        _ => Ok(Token::FixedBytes(w.to_vec())),
    }
}

pub fn decode_log(
    ev: &Event,
    topics: &[Vec<u8>],
    data: &[u8],
) -> Result<Vec<(String, Token)>, EthErr> {
    let indexed: Vec<&Param> = ev.inputs.iter().filter(|p| p.indexed).collect();
    let to_skip = if ev.anonymous { 0 } else { 1 };
    if !ev.anonymous {
        if topics.is_empty() {
            return Err(EthErr::InvalidData);
        }
        if topics[0] != keccak256(ev.signature().as_bytes()).to_vec() {
            return Err(EthErr::InvalidData);
        }
    }
    if topics.len() > indexed.len() + to_skip {
        return Err(EthErr::InvalidData);
    }
    let mut out: Vec<(String, Token)> = Vec::new();
    let mut idx = 0usize;
    for p in ev.inputs.iter() {
        if p.indexed {
            match topics.get(to_skip + idx) {
                Some(t) => {
                    out.push((p.name.clone(), word_to_token(&p.kind, t)?));
                }
                None => {
                    if topics.len() == to_skip {
                        return Err(EthErr::Long);
                    }
                    return Err(EthErr::InvalidData);
                }
            }
            idx += 1;
        }
    }
    // non-indexed params from data
    let kinds: Vec<ParamType> = ev
        .inputs
        .iter()
        .filter(|p| !p.indexed)
        .map(|p| p.kind.clone())
        .collect();
    let mut tokens = decode_types(&kinds, data)?;
    for p in ev.inputs.iter().filter(|p| !p.indexed) {
        let t = tokens.remove(0);
        out.push((p.name.clone(), t));
    }
    Ok(out)
}

// ---------------- ABI deserialization ----------------

pub fn load(entries: &[Node], reader: &Reader) -> Result<Contract, JErr> {
    let mut contract = Contract::default();
    for entry in entries {
        let obj = match &entry.val {
            Val::Obj(items) => items,
            Val::Arr(_) => {
                // sequences are handled like maps without a tag
                let items = match &entry.val {
                    Val::Arr(items) => items,
                    _ => unreachable!(),
                };
                if items.is_empty() {
                    return Err(reader.err_at("missing field `type`", entry.end));
                }
                let tag = &items[0];
                let tag_str = match &tag.val {
                    Val::Str(s) => s.clone(),
                    _ => {
                        return Err(reader.err_at(
                            &format!(
                                "invalid type: {}, expected variant identifier",
                                crate::json::unexpected_desc(tag)
                            ),
                            entry.end,
                        ))
                    }
                };
                return Err(reader.err_at(
                    &format!(
                        "unknown variant `{}`, expected one of `constructor`, `function`, `event`, `error`, `fallback`, `receive`",
                        tag_str
                    ),
                    entry.end,
                ));
            }
            _ => {
                let msg = format!(
                    "invalid type: {}, expected internally tagged enum Operation",
                    crate::json::unexpected_desc(entry)
                );
                let idx = if matches!(entry.val, Val::Num(Num::U(_)) | Val::Num(Num::I(_)) | Val::Num(Num::F(_))) {
                    usize::min(reader.s.len(), entry.end + 1)
                } else {
                    entry.end
                };
                return Err(reader.err_at(&msg, idx));
            }
        };
        // find the tag
        let mut tag: Option<(usize, String)> = None;
        let mut fields: Vec<(usize, String, &Node)> = Vec::new();
        for (k, v) in obj.iter() {
            let kn = match &k.val {
                Val::Str(s) => s.clone(),
                _ => String::new(),
            };
            if kn == "type" {
                if tag.is_some() {
                    let msg = "duplicate field `type`".to_string();
                    let idx = usize::min(reader.s.len(), v.start);
                    return Err(reader.err_at(&msg, idx));
                }
                match &v.val {
                    Val::Str(s) => tag = Some((v.end, s.clone())),
                    _ => {
                        let msg = format!(
                            "invalid type: {}, expected variant identifier",
                            crate::json::unexpected_desc(v)
                        );
                        return Err(reader.err_at(&msg, v.end));
                    }
                }
            } else {
                fields.push((v.start, kn, v));
            }
        }
        let (tag_end, tag) = match tag {
            Some(t) => t,
            None => return Err(reader.err_at("missing field `type`", entry.end)),
        };
        let _ = tag_end;
        let known = ["constructor", "function", "event", "error", "fallback", "receive"];
        if !known.contains(&tag.as_str()) {
            return Err(reader.err_at(
                &format!(
                    "unknown variant `{}`, expected one of `constructor`, `function`, `event`, `error`, `fallback`, `receive`",
                    tag
                ),
                tag_end,
            ));
        }
        match tag.as_str() {
            "fallback" | "receive" => {}
            "constructor" => {}
            "error" => {}
            "function" => {}
            "event" => {}
            _ => {}
        }
        // payload
        let mut name: Option<&Node> = None;
        let mut inputs: Option<&Node> = None;
        let mut outputs: Option<&Node> = None;
        let mut anonymous: Option<&Node> = None;
        let mut components: Option<&Node> = None;
        let mut sm: Option<&Node> = None;
        let mut constant: Option<&Node> = None;
        let mut payable: Option<&Node> = None;
        for (vstart, kn, v) in fields.iter() {
            match kn.as_str() {
                "name" => {
                    if name.is_some() {
                        let msg = "duplicate field `name`".to_string();
                        return Err(top_err(reader, entry, &msg));
                    }
                    name = Some(v);
                }
                "inputs" => {
                    if inputs.is_some() {
                        let msg = "duplicate field `inputs`".to_string();
                        return Err(top_err(reader, entry, &msg));
                    }
                    inputs = Some(v);
                }
                "outputs" => {
                    if outputs.is_some() {
                        let msg = "duplicate field `outputs`".to_string();
                        return Err(top_err(reader, entry, &msg));
                    }
                    outputs = Some(v);
                }
                "anonymous" => {
                    if anonymous.is_some() {
                        let msg = "duplicate field `anonymous`".to_string();
                        return Err(top_err(reader, entry, &msg));
                    }
                    anonymous = Some(v);
                }
                "components" => {
                    if components.is_some() {
                        let msg = "duplicate field `components`".to_string();
                        return Err(top_err(reader, entry, &msg));
                    }
                    components = Some(v);
                }
                "stateMutability" => {
                    sm = Some(v);
                }
                "constant" | "payable" => {
                    if let Val::Bool(_) = v.val {
                    } else {
                        let msg = format!(
                            "invalid type: {}, expected a boolean",
                            crate::json::unexpected_desc(v)
                        );
                        return Err(top_err(reader, entry, &msg));
                    }
                    if kn == "constant" {
                        constant = Some(v);
                    } else {
                        payable = Some(v);
                    }
                }
                _ => {}
            }
        }
        let _ = (sm, constant, payable);
        // required fields
        match tag.as_str() {
            "constructor" => {
                let inputs = match inputs {
                    Some(v) => v,
                    None => return Err(top_err(reader, entry, "missing field `inputs`")),
                };
                let _ = parse_params(inputs, reader, entry)?;
            }
            "error" => {
                let name = match name {
                    Some(v) => as_string(v, reader, entry)?,
                    None => return Err(top_err(reader, entry, "missing field `name`")),
                };
                let inputs = match inputs {
                    Some(v) => v,
                    None => return Err(top_err(reader, entry, "missing field `inputs`")),
                };
                let _ = (name, parse_params(inputs, reader, entry)?);
            }
            "function" => {
                let name = match name {
                    Some(v) => as_string(v, reader, entry)?,
                    None => return Err(top_err(reader, entry, "missing field `name`")),
                };
                let inputs = match inputs {
                    Some(v) => v,
                    None => return Err(top_err(reader, entry, "missing field `inputs`")),
                };
                let outputs = match outputs {
                    Some(v) => v,
                    None => return Err(top_err(reader, entry, "missing field `outputs`")),
                };
                let f = Function {
                    name,
                    inputs: parse_params(inputs, reader, entry)?,
                    outputs: parse_params(outputs, reader, entry)?,
                };
                contract.functions.entry(f.name.clone()).or_default().push(f);
            }
            "event" => {
                let name = match name {
                    Some(v) => as_string(v, reader, entry)?,
                    None => return Err(top_err(reader, entry, "missing field `name`")),
                };
                let inputs = match inputs {
                    Some(v) => v,
                    None => return Err(top_err(reader, entry, "missing field `inputs`")),
                };
                let anonymous = match anonymous {
                    Some(v) => match &v.val {
                        Val::Bool(b) => *b,
                        _ => {
                            let msg = format!(
                                "invalid type: {}, expected a boolean",
                                crate::json::unexpected_desc(v)
                            );
                            return Err(top_err(reader, entry, &msg));
                        }
                    },
                    None => return Err(top_err(reader, entry, "missing field `anonymous`")),
                };
                let e = Event {
                    name,
                    inputs: parse_params(inputs, reader, entry)?,
                    anonymous,
                };
                contract.events.entry(e.name.clone()).or_default().push(e);
            }
            _ => {}
        }
    }
    Ok(contract)
}

fn top_err(reader: &Reader, entry: &Node, msg: &str) -> JErr {
    // position determined by the outer sequence handling
    let idx = crate::json::top_fix_index(reader.s, entry.end);
    reader.err_at(msg, idx)
}

fn as_string(v: &Node, reader: &Reader, entry: &Node) -> Result<String, JErr> {
    match &v.val {
        Val::Str(s) => Ok(s.clone()),
        _ => Err(top_err(
            reader,
            entry,
            &format!("invalid type: {}, expected a string", crate::json::unexpected_desc(v)),
        )),
    }
}

fn parse_params(arr: &Node, reader: &Reader, entry: &Node) -> Result<Vec<Param>, JErr> {
    let items = match &arr.val {
        Val::Arr(items) => items,
        _ => {
            return Err(top_err(
                reader,
                entry,
                &format!("invalid type: {}, expected a sequence", crate::json::unexpected_desc(arr)),
            ))
        }
    };
    let mut out = Vec::new();
    for item in items {
        let obj = match &item.val {
            Val::Obj(items) => items,
            _ => {
                return Err(top_err(
                    reader,
                    entry,
                    &format!(
                        "invalid type: {}, expected a valid event parameter spec",
                        crate::json::unexpected_desc(item)
                    ),
                ))
            }
        };
        let mut name = String::new();
        let mut kind_str: Option<&Node> = None;
        let mut indexed = false;
        let mut comps: Option<&Node> = None;
        let mut seen_name = false;
        let mut seen_kind = false;
        let mut seen_indexed = false;
        let mut seen_comps = false;
        for (k, v) in obj.iter() {
            let kn = match &k.val {
                Val::Str(s) => s.clone(),
                _ => String::new(),
            };
            match kn.as_str() {
                "name" => {
                    if seen_name {
                        return Err(top_err(reader, entry, "duplicate field `name`"));
                    }
                    seen_name = true;
                    name = match &v.val {
                        Val::Str(s) => s.clone(),
                        _ => {
                            return Err(top_err(
                                reader,
                                entry,
                                &format!("invalid type: {}, expected a string", crate::json::unexpected_desc(v)),
                            ))
                        }
                    };
                }
                "type" => {
                    if seen_kind {
                        return Err(top_err(reader, entry, "duplicate field `type`"));
                    }
                    seen_kind = true;
                    kind_str = Some(v);
                }
                "indexed" => {
                    if seen_indexed {
                        return Err(top_err(reader, entry, "duplicate field `indexed`"));
                    }
                    seen_indexed = true;
                    indexed = match &v.val {
                        Val::Bool(b) => *b,
                        _ => {
                            return Err(top_err(
                                reader,
                                entry,
                                &format!("invalid type: {}, expected a boolean", crate::json::unexpected_desc(v)),
                            ))
                        }
                    };
                }
                "components" => {
                    if seen_comps {
                        return Err(top_err(reader, entry, "duplicate field `components`"));
                    }
                    seen_comps = true;
                    comps = Some(v);
                }
                _ => {}
            }
        }
        let tv = match kind_str {
            Some(v) => v,
            None => {
                if !seen_name {
                    return Err(top_err(reader, entry, "missing field `name`"));
                }
                return Err(top_err(reader, entry, "missing field `kind`"));
            }
        };
        let ts = match &tv.val {
            Val::Str(s) => s.clone(),
            _ => {
                return Err(top_err(
                    reader,
                    entry,
                    &format!(
                        "invalid type: {}, expected a correct name of abi-encodable parameter type",
                        crate::json::unexpected_desc(tv)
                    ),
                ))
            }
        };
        let kind = match ParamType::parse(&ts) {
            Ok(k) => k,
            Err(e) => return Err(top_err(reader, entry, &e.serde_debug())),
        };
        if matches!(kind, ParamType::Tuple(_)) && comps.is_none() {
            return Err(top_err(reader, entry, "missing field `components`"));
        }
        let kind = if let (ParamType::Tuple(_), Some(c)) = (&kind, comps) {
            let items = match &c.val {
                Val::Arr(items) => items,
                _ => {
                    return Err(top_err(
                        reader,
                        entry,
                        &format!("invalid type: {}, expected a sequence", crate::json::unexpected_desc(c)),
                    ))
                }
            };
            let sub = parse_params_raw(items, reader, entry)?;
            ParamType::Tuple(sub.iter().map(|p| p.kind.clone()).collect())
        } else {
            kind
        };
        out.push(Param { name, kind, indexed });
    }
    Ok(out)
