        return Err(required_err(bin, level, &missing, &used4(&topics), &positionals_names));
    }
    Ok(Action::DecodeLog {
        abi: positionals[0].clone(),
        name: positionals[1].clone(),
        topics,
        data: positionals[2].clone(),
    })
}

fn used4(topics: &[String]) -> Vec<String> {
    if topics.is_empty() {
        vec![]
    } else {
        vec!["-l <topic>...".to_string()]
    }
}

pub fn print_stdout(s: &str) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(s.as_bytes());
}
