pub struct ClapError {
    pub msg: String,
}

fn usage_for(level: Level, bin: &str) -> String {
    let path: Vec<&str> = match level {
        Level::Top => vec![],
        Level::Encode => vec!["encode"],
        Level::EncodeFunction => vec!["encode", "function"],
        Level::EncodeParams => vec!["encode", "params"],
        Level::Decode => vec!["decode"],
        Level::DecodeFunction => vec!["decode", "function"],
        Level::DecodeParams => vec!["decode", "params"],
        Level::DecodeLog => vec!["decode", "log"],
        Level::Help => vec!["help"],
    };
    let mut s = bin.to_string();
    for p in path {
        s.push(' ');
        s.push_str(p);
    }
    s
}

/// default (help) usage suffix for a level
fn default_usage(level: Level, bin: &str) -> String {
    let base = usage_for(level, bin);
    match level {
        Level::Top => format!("{} <SUBCOMMAND>", base),
        Level::Encode => format!("{} <SUBCOMMAND>", base),
        Level::Decode => format!("{} <SUBCOMMAND>", base),
        Level::EncodeFunction => format!(
            "{} [FLAGS] [OPTIONS] <abi-path> <function-name-or-signature>",
            base
        ),
        Level::EncodeParams => format!("{} [FLAGS] [OPTIONS]", base),
        Level::DecodeFunction => format!("{} <abi-path> <function-name-or-signature> <data>", base),
        Level::DecodeParams => format!("{} [OPTIONS] <data>", base),
        Level::DecodeLog => format!(
            "{} [OPTIONS] <abi-path> <event-name-or-signature> <data>",
            base
        ),
        Level::Help => format!("\t{} <subcommands>...", base),
    }
}

fn smart_usage(level: Level, bin: &str, positionals: &[&str], used: &[String]) -> String {
    let mut s = usage_for(level, bin);
    for p in positionals {
        s.push(' ');
        s.push_str(p);
    }
    for u in used {
        s.push(' ');
        s.push_str(u);
    }
    s
}

fn err_out(msg: &str) -> ClapError {
    ClapError { msg: msg.to_string() }
}

fn unknown_arg(bin: &str, level: Level, arg: &str, suggestion: Option<&str>, used: &[String], positionals: &[&str], extra_used: Option<&str>) -> ClapError {
    let mut msg = String::new();
    msg.push_str(&format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    ));
    if let Some(s) = suggestion {
        msg.push_str(&format!("\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?", s));
    }
    msg.push_str("\n\nUSAGE:\n    ");
    let usage = if used.is_empty() && extra_used.is_none() {
        default_usage(level, bin)
    } else {
        let mut u = used.to_vec();
        if let Some(e) = extra_used {
            u.push(e.to_string());
        }
        smart_usage(level, bin, positionals, &u)
    };
    if usage.starts_with('\t') {
        msg.push_str(&usage);
    } else {
        msg.push_str(&usage);
    }
    msg.push_str("\n\nFor more information try --help");
    err_out(&msg)
}

fn required_err(bin: &str, level: Level, missing: &[&str], used: &[String], positionals: &[&str]) -> ClapError {
    let mut msg = String::from("error: The following required arguments were not provided:");
    for m in missing {
        msg.push_str(&format!("\n    {}", m));
    }
    msg.push_str("\n\nUSAGE:\n    ");
    if used.is_empty() {
        msg.push_str(&default_usage(level, bin));
    } else {
        msg.push_str(&smart_usage(level, bin, positionals, used));
    }
    msg.push_str("\n\nFor more information try --help");
    err_out(&msg)
}

fn value_err(bin: &str, level: Level, arg: &str, kind: &str, used: &[String], positionals: &[&str]) -> ClapError {
    let msg = format!(
        "error: The argument '{}' {}\n\nUSAGE:\n    {}\n\nFor more information try --help",
        arg,
        kind,
        if used.is_empty() {
            default_usage(level, bin)
        } else {
            smart_usage(level, bin, positionals, used)
        }
    );
    err_out(&msg)
}

fn did_you_mean(arg: &str, candidates: &[&str]) -> Option<&'static str> {
    let mut best: Option<(f64, usize)> = None;
    for (i, c) in candidates.iter().enumerate() {
        let conf = jaro_winkler(arg, c);
        if conf > 0.8 && (best.is_none() || best.unwrap().0 < conf) {
            best = Some((conf, i));
        }
    }
    best.map(|(_, i)| match i {
        0 => "help",
        1 => "version",
        2 => "lenient",
        3 => "topic",
        4 => "type",
        _ => candidates[i],
    })
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let s1: Vec<char> = a.chars().collect();
    let s2: Vec<char> = b.chars().collect();
    if s1.is_empty() || s2.is_empty() {
        return 0.0;
    }
    let l1 = s1.len();
    let l2 = s2.len();
    let md = (usize::max(l1, l2) / 2).saturating_sub(1);
    let mut f1 = vec![false; l1];
    let mut f2 = vec![false; l2];
    let mut m = 0usize;
    for i in 0..l1 {
        let lo = i.saturating_sub(md);
        let hi = usize::min(l2, i + md + 1);
        for j in lo..hi {
            if f2[j] || s1[i] != s2[j] {
                continue;
            }
            f1[i] = true;
            f2[j] = true;
            m += 1;
            break;
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..l1 {
        if !f1[i] {
            continue;
        }
        while !f2[k] {
            k += 1;
        }
        if s1[i] != s2[k] {
            t += 1;
        }
        k += 1;
    }
    t /= 2;
    let jaro = (m as f64 / l1 as f64 + m as f64 / l2 as f64 + (m - t) as f64 / m as f64) / 3.0;
    if jaro <= 0.7 {
        return jaro;
    }
    let mut l = 0usize;
    for i in 0..usize::min(4, usize::min(l1, l2)) {
        if s1[i] != s2[i] {
            break;
        }
        l += 1;
    }
    jaro + l as f64 * 0.1 * (1.0 - jaro)
}

pub enum Action {
    Print(String),
    EncodeFunction { abi: String, name: String, params: Vec<String>, lenient: bool },
    EncodeParams { pairs: Vec<(String, String)>, lenient: bool },
    DecodeFunction { abi: String, name: String, data: String },
    DecodeParams { types: Vec<String>, data: String },
    DecodeLog { abi: String, name: String, topics: Vec<String>, data: String },
}

pub struct Parsed {
    pub action: Action,
}

pub fn run(argv: &[String], bin: &str) -> Result<Action, ClapError> {
    let mut i = 0usize;
    // top level
    let mut positionals: Vec<String> = Vec::new();
    while i < argv.len() {
        let a = &argv[i];
        if a == "--" {
            for x in &argv[i + 1..] {
                positionals.push(x.clone());
            }
            i = argv.len();
            break;
        }
        if a == "-h" || a == "--help" {
            let long = a == "--help";
            return Ok(Action::Print(help_text(Level::Top, bin, long)));
        }
        if a == "-V" || a == "--version" {
            return Ok(Action::Print(format!("{} {}\n", APP_NAME, VERSION)));
        }
        if a.starts_with("--") {
            let name = a.trim_start_matches("--");
            let name = name.split('=').next().unwrap_or(name);
            let sugg = did_you_mean(name, &["help", "version"]);
            return Err(unknown_arg(bin, Level::Top, a, sugg, &[], &[], None));
        }
        if a.starts_with('-') && a.len() > 1 {
            for c in a[1..].chars() {
                match c {
                    'h' => return Ok(Action::Print(help_text(Level::Top, bin, false))),
                    'V' => return Ok(Action::Print(format!("{} {}\n", APP_NAME, VERSION))),
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            Level::Top,
                            &format!("-{}", c),
                            None,
                            &[],
                            &[],
                            None,
                        ))
                    }
                }
            }
            i += 1;
            continue;
        }
        positionals.push(a.clone());
        i += 1;
    }
    if positionals.is_empty() {
        return Err(err_out(&format!(
            "error: Found argument '' which wasn't expected, or isn't valid in this context"
        )));
    }
    let sub = positionals.remove(0).clone();
    match sub.as_str() {
        "encode" => run_encode(&positionals, bin),
        "decode" => run_decode(&positionals, bin),
        "help" => run_help(&positionals, bin),
        _ => {
            let candidates = ["decode", "encode", "help"];
            let sugg = did_you_mean(&sub, &candidates);
            if let Some(s) = sugg {
                let path = usage_for(Level::Top, bin);
                let msg = format!(
                    "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help",
                    sub, s, path, sub, default_usage(Level::Top, bin)
                );
                return Err(err_out(&msg));
            }
            Err(unknown_arg(bin, Level::Top, &sub, None, &[], &[], None))
        }
    }
}

fn run_help(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    // walk subcommand path
    let mut level = Level::Top;
    let mut path: Vec<&str> = Vec::new();
    for name in rest {
        let allowed: Vec<&str> = match level {
            Level::Top => vec!["decode", "encode", "help"],
            Level::Encode => vec!["function", "help", "params"],
            Level::Decode => vec!["function", "help", "log", "params"],
            _ => vec![],
        };
        if !allowed.contains(&name.as_str()) {
            let msg = format!(
                "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help",
                name,
                bin
            );
            return Err(err_out(&msg));
        }
        level = match (level, name.as_str()) {
            (Level::Top, "decode") => Level::Decode,
            (Level::Top, "encode") => Level::Encode,
            (Level::Top, "help") => Level::Help,
            (Level::Encode, "function") => Level::EncodeFunction,
            (Level::Encode, "params") => Level::EncodeParams,
            (Level::Decode, "function") => Level::DecodeFunction,
            (Level::Decode, "log") => Level::DecodeLog,
            (Level::Decode, "params") => Level::DecodeParams,
            _ => Level::Help,
        };
        path.push(match name.as_str() {
            "decode" => "decode",
            "encode" => "encode",
            "help" => "help",
            "function" => "function",
            "params" => "params",
            "log" => "log",
            _ => "",
        });
    }
    let p: Vec<&str> = path;
    let binpath: String = {
        let mut s = bin.to_string();
        for x in &p {
            s.push('-');
            s.push_str(x);
        }
        s
    };
    Ok(Action::Print(help_text(level, &binpath, true)))
}

fn run_encode(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 0usize;
    while i < rest.len() {
        let a = &rest[i];
        if a == "--" {
            for x in &rest[i + 1..] {
                positionals.push(x.clone());
            }
            i = rest.len();
            break;
        }
        if a == "-h" || a == "--help" {
            return Ok(Action::Print(help_text(Level::Encode, bin, a == "--help")));
        }
        if a == "-V" || a == "--version" {
            return Ok(Action::Print(format!("{}-encode {}\n", bin, VERSION)));
        }
        if a.starts_with("--") {
            let name = a.trim_start_matches("--").split('=').next().unwrap_or(a.trim_start_matches("--"));
            let sugg = did_you_mean(name, &["help", "version"]);
            return Err(unknown_arg(bin, Level::Encode, a, sugg, &[], &[], None));
        }
        if a.starts_with('-') && a.len() > 1 {
            for c in a[1..].chars() {
                match c {
                    'h' => return Ok(Action::Print(help_text(Level::Encode, bin, false))),
                    'V' => return Ok(Action::Print(format!("{}-encode {}\n", bin, VERSION))),
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            Level::Encode,
                            &format!("-{}", c),
                            None,
                            &[],
                            &[],
                            None,
                        ))
                    }
                }
            }
            i += 1;
            continue;
        }
        positionals.push(a.clone());
        i += 1;
    }
    if positionals.is_empty() {
        return Err(err_out(&format!(
            "error: Found argument '' which wasn't expected, or isn't valid in this context"
        )));
    }
    let sub = positionals.remove(0).clone();
    match sub.as_str() {
        "function" => parse_encode_function(&positionals, bin),
        "params" => parse_encode_params(&positionals, bin),
        "help" => run_help(&positionals, bin),
        _ => {
            let candidates = ["function", "help", "params"];
            let sugg = did_you_mean(&sub, &candidates);
            if let Some(s) = sugg {
                let path = usage_for(Level::Encode, bin);
                let msg = format!(
                    "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help",
                    sub, s, path, sub, default_usage(Level::Encode, bin)
                );
                return Err(err_out(&msg));
            }
            Err(unknown_arg(bin, Level::Encode, &sub, None, &[], &[], None))
        }
    }
}

