        }
        if a.starts_with('-') && a.len() > 1 {
            for c in a[1..].chars() {
                match c {
                    'h' => return Ok(Action::Print(help_text(Level::Decode, bin, false))),
                    'V' => return Ok(Action::Print(format!("{}-decode {}\n", bin, VERSION))),
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            Level::Decode,
                            &format!("-{}", c),
                            None,
                            &[],
                            &[],
                            None,
                        ))
                    }
                }
            }
            i += 1;
            continue;
        }
        positionals.push(a.clone());
        i += 1;
    }
    if positionals.is_empty() {
        return Err(err_out(&format!(
            "error: Found argument '' which wasn't expected, or isn't valid in this context"
        )));
    }
    let sub = positionals.remove(0).clone();
    match sub.as_str() {
        "function" => parse_decode_function(&positionals, bin),
        "log" => parse_decode_log(&positionals, bin),
        "params" => parse_decode_params(&positionals, bin),
        "help" => run_help(&positionals, bin),
        _ => {
            let candidates = ["decode", "encode", "help", "function", "log", "params"];
            let sugg = did_you_mean(&sub, &["function", "log", "params", "help"]);
            let _ = candidates;
            if let Some(s) = sugg {
                let path = usage_for(Level::Decode, bin);
                let msg = format!(
                    "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help",
                    sub, s, path, sub, default_usage(Level::Decode, bin)
                );
                return Err(err_out(&msg));
            }
            Err(unknown_arg(bin, Level::Decode, &sub, None, &[], &[], None))
        }
    }
}

struct OptState {
    lenient: bool,
