fn parse_encode_function(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::EncodeFunction;
    let positionals_names = ["<abi-path>", "<function-name-or-signature>"];
    let mut positionals: Vec<String> = Vec::new();
    let mut params: Vec<String> = Vec::new();
    let mut lenient = 0usize;
    let mut pending_p: Vec<Option<String>> = Vec::new();
    let mut i = 0usize;
    let mut after_dd = false;
    while i < rest.len() {
        let a = &rest[i];
        if after_dd {
            push_positional(&mut positionals, positionals_names, a, bin, level, &used_args(lenient, &params))?;
            i += 1;
            continue;
        }
        if a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(format!("{}-encode-function {}\n", bin, VERSION)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            if name == "lenient" {
                lenient += 1;
                i += 1;
                continue;
            }
            let sugg = did_you_mean(name, &["help", "lenient", "version"]);
            let extra = sugg.map(|s| format!("--{}", s));
            return Err(unknown_arg(bin, level, a, sugg, &used_args(lenient, &params), &positionals_names, extra.as_deref()));
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed_next = false;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(format!("{}-encode-function {}\n", bin, VERSION))),
                    'l' => {
                        lenient += 1;
                    }
                    'p' => {
                        let rest_str: String = chars[ci + 1..].iter().collect();
                        let rest_str = rest_str.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest_str);
                        if !rest_str.is_empty() {
                            params.push(rest_str);
                            ci = chars.len();
                            break;
                        } else {
                            // value from next arg if it does not start with '-'
                            let next = rest.get(i + 1);
                            match next {
                                Some(n) if !n.starts_with('-') => {
                                    params.push(n.clone());
                                    consumed_next = true;
                                    ci = chars.len();
                                    break;
                                }
                                _ => {
                                    pending_p.push(None);
                                    ci = chars.len();
                                    break;
                                }
                            }
                        }
                    }
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &used_args(lenient, &params),
                            &positionals_names,
                            None,
                        ))
                    }
                }
                ci += 1;
            }
            i += 1;
            if consumed_next {
                i += 1;
            }
            continue;
        }
        push_positional(&mut positionals, positionals_names, a, bin, level, &used_args(lenient, &params))?;
        i += 1;
    }
    if lenient > 1 {
        let u = used_args(lenient, &params);
        return Err(value_err(bin, level, "--lenient", "was provided more than once, but cannot be used multiple times", &u, &positionals_names));
    }
    if !pending_p.is_empty() && params.is_empty() {
        let u = used_args(lenient, &params);
        return Err(value_err(bin, level, "-p <params>...", "requires a value but none was supplied", &u, &positionals_names));
    }
    if positionals.len() < 2 {
        let missing: Vec<&str> = positionals_names[positionals.len()..].to_vec();
        let u = used_args(lenient, &params);
        return Err(required_err(bin, level, &missing, &u, &positionals_names));
    }
    Ok(Action::EncodeFunction {
        abi: positionals[0].clone(),
        name: positionals[1].clone(),
        params,
        lenient: lenient > 0,
    })
}

fn used_args(lenient: usize, params: &[String]) -> Vec<String> {
    let mut u = Vec::new();
    if lenient > 0 {
        u.push("--lenient".to_string());
    }
    if !params.is_empty() {
        u.push("-p <params>...".to_string());
    }
    u
}

fn push_positional(
    positionals: &mut Vec<String>,
    names: &[&str],
    a: &str,
    bin: &str,
    level: Level,
    used: &[String],
) -> Result<(), ClapError> {
    if positionals.len() >= names.len() {
        return Err(unknown_arg(bin, level, a, None, used, names, None));
    }
    positionals.push(a.to_string());
    Ok(())
}

fn parse_encode_params(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::EncodeParams;
    let positionals_names: [&str; 0] = [];
    let mut pairs: Vec<(String, String)> = Vec::new();
    let mut lenient = 0usize;
    let mut i = 0usize;
    let mut pending: Vec<Vec<String>> = Vec::new();
    while i < rest.len() {
        let a = &rest[i];
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(format!("{}-encode-params {}\n", bin, VERSION)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            if name == "lenient" {
                lenient += 1;
                i += 1;
                continue;
            }
            let sugg = did_you_mean(name, &["help", "lenient", "version"]);
            let extra = sugg.map(|s| format!("--{}", s));
            return Err(unknown_arg(bin, level, a, sugg, &used2(lenient, &pairs), &positionals_names, extra.as_deref()));
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(format!("{}-encode-params {}\n", bin, VERSION))),
                    'l' => {
                        lenient += 1;
                    }
                    'v' => {
                        let rest_str: String = chars[ci + 1..].iter().collect();
                        let mut vals: Vec<String> = Vec::new();
                        let rs = rest_str.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest_str);
                        if !rs.is_empty() {
                            vals.push(rs);
                        }
                        // take up to 2 values unconditionally from following args
                        while vals.len() < 2 && i + 1 + consumed < rest.len() {
                            vals.push(rest[i + 1 + consumed].clone());
                            consumed += 1;
                        }
                        if vals.is_empty() {
                            pending.push(vec![]);
                        } else {
                            pending.push(vals);
                        }
                        ci = chars.len();
                        break;
                    }
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &used2(lenient, &pairs),
                            &positionals_names,
                            None,
                        ))
                    }
                }
                ci += 1;
            }
            i += 1 + consumed;
            continue;
        }
        // positional: not allowed
        return Err(unknown_arg(bin, level, a, None, &used2(lenient, &pairs), &positionals_names, None));
    }
    if lenient > 1 {
        return Err(value_err(bin, level, "--lenient", "was provided more than once, but cannot be used multiple times", &used2(lenient, &pairs), &positionals_names));
    }
    for p in pending.iter() {
        if p.is_empty() {
            return Err(value_err(bin, level, "-v <type-or-param> <type-or-param>", "requires a value but none was supplied", &used2(lenient, &pairs), &positionals_names));
        }
        if p.len() == 1 {
            return Err(value_err(bin, level, "-v <type-or-param> <type-or-param>", "requires 2 values, but 1 was provided", &used2(lenient, &pairs), &positionals_names));
        }
        pairs.push((p[0].clone(), p[1].clone()));
    }
    Ok(Action::EncodeParams { pairs, lenient: lenient > 0 })
}

fn used2(lenient: usize, pairs: &[(String, String)]) -> Vec<String> {
    let mut u = Vec::new();
    if lenient > 0 {
        u.push("--lenient".to_string());
    }
    if !pairs.is_empty() {
        u.push("-v <type-or-param> <type-or-param>".to_string());
    }
    u
}

