                "error: The subcommand '{}' wasn't recognized\\n\\nUSAGE:\\n\\t{} help <subcommands>...\\n\\nFor more information try --help",
                name, bin
            );
            return Err(err_out(&msg));
        }
        level = match (level, name.as_str()) {
            (Level::Top, "decode") => Level::Decode,
            (Level::Top, "encode") => Level::Encode,
            (Level::Top, "help") => Level::Help,
            (Level::Encode, "function") => Level::EncodeFunction,
            (Level::Encode, "params") => Level::EncodeParams,
            (Level::Decode, "function") => Level::DecodeFunction,
            (Level::Decode, "log") => Level::DecodeLog,
            (Level::Decode, "params") => Level::DecodeParams,
            _ => Level::Help,
        };
    }
    Ok(Action::Print(help_text(level, bin, true)))
}

fn subcommand_names(level: Level) -> Vec<&'static str> {
    match level {
        Level::Top => vec!["decode", "encode", "help"],
        Level::Encode => vec!["function", "help", "params"],
        Level::Decode => vec!["function", "help", "log", "params"],
        _ => vec![],
    }
}

fn level_path(level: Level) -> Vec<&'static str> {
    match level {
        Level::Top => vec![],
        Level::Encode => vec!["encode"],
        Level::Decode => vec!["decode"],
        Level::EncodeFunction => vec!["encode", "function"],
        Level::EncodeParams => vec!["encode", "params"],
        Level::DecodeFunction => vec!["decode", "function"],
        Level::DecodeParams => vec!["decode", "params"],
        Level::DecodeLog => vec!["decode", "log"],
        Level::Help => vec!["help"],
    }
}

fn parse_level(level: Level, argv: &[String], bin: &str, depth: usize) -> Result<Action, ClapError> {
    let subs = subcommand_names(level);
    if !subs.is_empty() {
        // intermediate level: no positionals allowed except subcommand names
        let mut i = 0usize;
        while i < argv.len() {
            let a = &argv[i];
            if a == "-h" || a == "--help" {
                return Ok(Action::Print(help_text(level, bin, a == "--help")));
            }
            if a == "-V" || a == "--version" {
                return Ok(Action::Print(format!("{}\\n", version_line(level, bin))));
            }
            if let Some(r) = leaf_long_flag(level, bin, a, &[], &[]) {
                return match r {
                    Ok(x) => Ok(x),
                    Err(e) => Err(e),
                };
            }
            if a == "--" {
                // remaining are positionals
                if i + 1 < argv.len() {
                    return Err(unknown_arg(bin, level, &argv[i + 1], None, &[], &[], None));
                }
                return Err(err_out("error: Found argument '' which wasn't expected, or isn't valid in this context"));
            }
            if a.starts_with('-') && a.len() > 1 {
                for c in a[1..].chars() {
                    match c {
                        'h' => return Ok(Action::Print(help_text(level, bin, false))),
                        'V' => return Ok(Action::Print(format!("{}\\n", version_line(level, bin)))),
                        _ => {
                            return Err(unknown_arg(
                                bin,
                                level,
                                &format!("-{}", c),
                                None,
                                &[],
                                &[],
                                None,
                            ))
                        }
                    }
                }
                i += 1;
                continue;
            }
            if subs.contains(&a.as_str()) {
                let next = match (level, a.as_str()) {
                    (Level::Top, "encode") => Level::Encode,
                    (Level::Top, "decode") => Level::Decode,
                    (Level::Encode, "function") => Level::EncodeFunction,
                    (Level::Encode, "params") => Level::EncodeParams,
                    (Level::Decode, "function") => Level::DecodeFunction,
                    (Level::Decode, "log") => Level::DecodeLog,
                    (Level::Decode, "params") => Level::DecodeParams,
                    _ => Level::Help,
                };
                if a == "help" {
                    return run_help(&argv[i + 1..], bin);
                }
                return parse_level(next, &argv[i + 1..], bin, depth + 1);
            }
            // not a subcommand: did-you-mean?
            let sugg = did_you_mean(a, &subs);
            if let Some(s) = sugg {
                let path = usage_for(level, bin);
                let msg = format!(
                    "error: The subcommand '{}' wasn't recognized\\n\\tDid you mean '{}'?\\n\\nIf you believe you received this message in error, try re-running with '{} -- {}'\\n\\nUSAGE:\\n    {}\\n\\nFor more information try --help",
                    a, s, path, a, default_usage(level, bin)
                );
                return Err(err_out(&msg));
            }
            return Err(unknown_arg(bin, level, a, None, &[], &[], None));
        }
        return Err(err_out("error: Found argument '' which wasn't expected, or isn't valid in this context"));
    }
    match level {
        Level::EncodeFunction => parse_encode_function(argv, bin),
        Level::EncodeParams => parse_encode_params(argv, bin),
        Level::DecodeFunction => parse_decode_function(argv, bin),
        Level::DecodeParams => parse_decode_params(argv, bin),
        Level::DecodeLog => parse_decode_log(argv, bin),
        _ => Err(err_out("error: internal")),
    }
}

fn used_args(lenient: usize, params: &[String]) -> Vec<String> {
    let mut u = Vec::new();
    if lenient > 0 {
        u.push("--lenient".to_string());
    }
    if !params.is_empty() {
        u.push("-p <params>...".to_string());
    }
    u
}

fn push_positional(
    positionals: &mut Vec<String>,
    names: &[&str],
    a: &str,
    bin: &str,
    level: Level,
    used: &[String],
) -> Result<(), ClapError> {
    if positionals.len() >= names.len() {
        return Err(unknown_arg(bin, level, a, None, used, names, None));
    }
    positionals.push(a.to_string());
    Ok(())
}

fn parse_encode_function(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::EncodeFunction;
    let positionals_names: &[&str] = &["<abi-path>", "<function-name-or-signature>"];
    let mut positionals: Vec<String> = Vec::new();
    let mut params: Vec<String> = Vec::new();
    let mut lenient = 0usize;
    let mut pending_p = 0usize;
    let mut i = 0usize;
    let mut after_dd = false;
    while i < rest.len() {
        let a = &rest[i];
        if after_dd {
            push_positional(&mut positionals, positionals_names, a, bin, level, &used_args(lenient, &params))?;
            i += 1;
            continue;
        }
        if a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(leaf_version(level, bin)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            if name == "lenient" {
                lenient += 1;
                i += 1;
                continue;
            }
            let sugg = did_you_mean(name, &["help", "lenient", "version"]);
            let extra = sugg.as_ref().map(|s| format!("--{}", s));
            return Err(unknown_arg(bin, level, a, sugg, &used_args(lenient, &params), positionals_names, extra.as_deref()));
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed_next = false;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(leaf_version(level, bin))),
                    'l' => {
                        lenient += 1;
                    }
                    'p' => {
                        let rest_str: String = chars[ci + 1..].iter().collect();
                        let rs = rest_str.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest_str);
                        if !rs.is_empty() {
                            params.push(rs);
                        } else {
                            let next = rest.get(i + 1);
                            match next {
                                Some(n) if !n.starts_with('-') => {
                                    params.push(n.clone());
                                    consumed_next = true;
                                }
                                _ => pending_p += 1,
                            }
                        }
                        ci = chars.len();
                        break;
                    }
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &used_args(lenient, &params),
                            positionals_names,
                            None,
                        ))
                    }
                }
                ci += 1;
            }
            i += 1;
            if consumed_next {
                i += 1;
            }
            continue;
        }
        push_positional(&mut positionals, positionals_names, a, bin, level, &used_args(lenient, &params))?;
        i += 1;
    }
    if lenient > 1 {
        let u = used_args(lenient, &params);
        return Err(value_err(bin, level, "--lenient", "was provided more than once, but cannot be used multiple times", &u, positionals_names));
    }
    if pending_p > 0 && params.is_empty() {
        let u = used_args(lenient, &params);
        return Err(value_err(bin, level, "-p <params>...", "requires a value but none was supplied", &u, positionals_names));
    }
    if positionals.len() < 2 {
        let missing: Vec<&str> = positionals_names[positionals.len()..].to_vec();
        let u = used_args(lenient, &params);
        return Err(required_err(bin, level, &missing, &u, positionals_names));
    }
    Ok(Action::EncodeFunction {
        abi: positionals[0].clone(),
        name: positionals[1].clone(),
        params,
        lenient: lenient > 0,
    })
}

