fn parse_encode_params(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::EncodeParams;
    let positionals_names: &[&str] = &[];
    let mut pairs: Vec<(String, String)> = Vec::new();
    let mut lenient = 0usize;
    let mut pending: Vec<Vec<String>> = Vec::new();
    let mut i = 0usize;
    while i < rest.len() {
        let a = &rest[i];
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(leaf_version(level, bin)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            if name == "lenient" {
                lenient += 1;
                i += 1;
                continue;
            }
            let sugg = did_you_mean(name, &["help", "lenient", "version"]);
            let extra = sugg.as_ref().map(|s| format!("--{}", s));
            return Err(unknown_arg(bin, level, a, sugg, &used2(lenient, &pairs), positionals_names, extra.as_deref()));
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(leaf_version(level, bin))),
                    'l' => {
                        lenient += 1;
                    }
                    'v' => {
                        let rest_str: String = chars[ci + 1..].iter().collect();
                        let rs = rest_str.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest_str);
                        let mut vals: Vec<String> = Vec::new();
                        if !rs.is_empty() {
                            vals.push(rs);
                        }
                        while vals.len() < 2 && i + 1 + consumed < rest.len() {
                            vals.push(rest[i + 1 + consumed].clone());
                            consumed += 1;
                        }
                        pending.push(vals);
                        ci = chars.len();
                        break;
                    }
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &used2(lenient, &pairs),
                            positionals_names,
                            None,
                        ))
                    }
                }
                ci += 1;
            }
            i += 1 + consumed;
            continue;
        }
        return Err(unknown_arg(bin, level, a, None, &used2(lenient, &pairs), positionals_names, None));
    }
    if lenient > 1 {
        return Err(value_err(bin, level, "--lenient", "was provided more than once, but cannot be used multiple times", &used2(lenient, &pairs), positionals_names));
    }
    for p in pending.iter() {
        if p.is_empty() {
            return Err(value_err(bin, level, "-v <type-or-param> <type-or-param>", "requires a value but none was supplied", &used2(lenient, &pairs), positionals_names));
        }
        if p.len() == 1 {
            return Err(value_err(bin, level, "-v <type-or-param> <type-or-param>", "requires 2 values, but 1 was provided", &used2(lenient, &pairs), positionals_names));
        }
        pairs.push((p[0].clone(), p[1].clone()));
    }
    Ok(Action::EncodeParams { pairs, lenient: lenient > 0 })
}

