    if lenient > 0 {
        u.push("--lenient".to_string());
    }
    if !pairs.is_empty() {
        u.push("-v <type-or-param> <type-or-param>".to_string());
    }
    u
}

fn parse_encode_params(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::EncodeParams;
    let positionals_names: &[&str] = &[];
    let mut pairs: Vec<(String, String)> = Vec::new();
    let mut lenient = 0usize;
    let mut pending: Vec<Vec<String>> = Vec::new();
    let mut i = 0usize;
    while i < rest.len() {
        let a = &rest[i];
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(leaf_version(level, bin)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            if name == "lenient" {
                lenient += 1;
                i += 1;
                continue;
            }
            let sugg = did_you_mean(name, &["help", "lenient", "version"]);
            let extra = sugg.as_ref().map(|s| format!("--{}", s));
            return Err(unknown_arg(bin, level, a, sugg, &used2(lenient, &pairs), positionals_names, extra.as_deref()));
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(leaf_version(level, bin))),
                    'l' => {
                        lenient += 1;
                    }
                    'v' => {
                        let rest_str: String = chars[ci + 1..].iter().collect();
                        let rs = rest_str.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest_str);
                        let mut vals: Vec<String> = Vec::new();
                        if !rs.is_empty() {
                            vals.push(rs);
                        }
                        while vals.len() < 2 && i + 1 + consumed < rest.len() {
                            vals.push(rest[i + 1 + consumed].clone());
                            consumed += 1;
                        }
                        pending.push(vals);
                        ci = chars.len();
                        break;
                    }
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &used2(lenient, &pairs),
                            positionals_names,
                            None,
                        ))
                    }
                }
                ci += 1;
            }
            i += 1 + consumed;
            continue;
        }
        return Err(unknown_arg(bin, level, a, None, &used2(lenient, &pairs), positionals_names, None));
    }
    if lenient > 1 {
        return Err(value_err(bin, level, "--lenient", "was provided more than once, but cannot be used multiple times", &used2(lenient, &pairs), positionals_names));
    }
    for p in pending.iter() {
        if p.is_empty() {
            return Err(value_err(bin, level, "-v <type-or-param> <type-or-param>", "requires a value but none was supplied", &used2(lenient, &pairs), positionals_names));
        }
        if p.len() == 1 {
            return Err(value_err(bin, level, "-v <type-or-param> <type-or-param>", "requires 2 values, but 1 was provided", &used2(lenient, &pairs), positionals_names));
        }
        pairs.push((p[0].clone(), p[1].clone()));
    }
    Ok(Action::EncodeParams { pairs, lenient: lenient > 0 })
}

fn parse_decode_function(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::DecodeFunction;
    let positionals_names: &[&str] = &["<abi-path>", "<function-name-or-signature>", "<data>"];
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 0usize;
    let mut after_dd = false;
    while i < rest.len() {
        let a = &rest[i];
        if after_dd {
            push_positional(&mut positionals, positionals_names, a, bin, level, &[])?;
            i += 1;
            continue;
        }
        if a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(leaf_version(level, bin)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            let sugg = did_you_mean(name, &["help", "version"]);
            return Err(unknown_arg(bin, level, a, sugg, &[], positionals_names, None));
        }
        if a.starts_with('-') && a.len() > 1 {
            for c in a[1..].chars() {
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(leaf_version(level, bin))),
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &[],
                            positionals_names,
                            None,
                        ))
                    }
                }
            }
            i += 1;
            continue;
        }
        push_positional(&mut positionals, positionals_names, a, bin, level, &[])?;
        i += 1;
    }
    if positionals.len() < 3 {
        let missing: Vec<&str> = positionals_names[positionals.len()..].to_vec();
        return Err(required_err(bin, level, &missing, &[], positionals_names));
    }
    Ok(Action::DecodeFunction {
        abi: positionals[0].clone(),
        name: positionals[1].clone(),
        data: positionals[2].clone(),
    })
}

fn used3(types: &[String]) -> Vec<String> {
    if types.is_empty() {
        vec![]
    } else {
        vec!["-t <type>...".to_string()]
    }
}

fn parse_decode_params(rest: &[String], bin: &str) -> Result<Action, ClapError> {
    let level = Level::DecodeParams;
    let positionals_names: &[&str] = &["<data>"];
    let mut types: Vec<String> = Vec::new();
    let mut positionals: Vec<String> = Vec::new();
    let mut i = 0usize;
    let mut after_dd = false;
    while i < rest.len() {
        let a = &rest[i];
        if after_dd {
            push_positional(&mut positionals, positionals_names, a, bin, level, &used3(&types))?;
            i += 1;
            continue;
        }
        if a == "--" {
            after_dd = true;
            i += 1;
            continue;
        }
        if a == "--help" {
            return Ok(Action::Print(help_text(level, bin, true)));
        }
        if a == "--version" {
            return Ok(Action::Print(leaf_version(level, bin)));
        }
        if a.starts_with("--") {
            let raw = a.trim_start_matches("--");
            let name = raw.split('=').next().unwrap_or(raw);
            let sugg = did_you_mean(name, &["help", "version"]);
            return Err(unknown_arg(bin, level, a, sugg, &used3(&types), positionals_names, None));
        }
        if a.starts_with('-') && a.len() > 1 {
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed_next = false;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'h' => return Ok(Action::Print(help_text(level, bin, false))),
                    'V' => return Ok(Action::Print(leaf_version(level, bin))),
                    't' => {
                        let rest_str: String = chars[ci + 1..].iter().collect();
                        let rs = rest_str.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest_str);
                        if !rs.is_empty() {
                            types.push(rs);
                        } else {
                            let next = rest.get(i + 1);
                            match next {
                                Some(n) if !n.starts_with('-') => {
                                    types.push(n.clone());
                                    consumed_next = true;
                                }
                                _ => {}
                            }
                        }
                        ci = chars.len();
                        break;
                    }
                    _ => {
                        return Err(unknown_arg(
                            bin,
                            level,
                            &format!("-{}", c),
                            None,
                            &used3(&types),
                            positionals_names,
                            None,
                        ))
                    }
                }
                ci += 1;
            }
            i += 1;
            if consumed_next {
                i += 1;
            }
            continue;
        }
        push_positional(&mut positionals, positionals_names, a, bin, level, &used3(&types))?;
        i += 1;
    }
    if positionals.len() < 1 {
        return Err(required_err(bin, level, &["<data>"], &used3(&types), positionals_names));
    }
    Ok(Action::DecodeParams { types, data: positionals[0].clone() })
}

