{"command": "cd /workspace && cat > /tmp/jwtest.rs <<'EOF'
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let s1: Vec<char> = a.chars().collect();
    let s2: Vec<char> = b.chars().collect();
    if s1.is_empty() || s2.is_empty() { return 0.0; }
    let l1 = s1.len();
    let l2 = s2.len();
    let md = (usize::max(l1, l2) / 2).saturating_sub(1);
    let mut f1 = vec![false; l1];
    let mut f2 = vec![false; l2];
    let mut m = 0usize;
    for i in 0..l1 {
        let lo = i.saturating_sub(md);
        let hi = usize::min(l2, i + md + 1);
        for j in lo..hi {
            if f2[j] || s1[i] != s2[j] { continue; }
            f1[i] = true; f2[j] = true; m += 1; break;
        }
    }
    if m == 0 { return 0.0; }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..l1 {
        if !f1[i] { continue; }
        while !f2[k] { k += 1; }
        if s1[i] != s2[k] { t += 1; }
        k += 1;
    }
    t /= 2;
    let jaro = (m as f64 / l1 as f64 + m as f64 / l2 as f64 + (m - t) as f64 / m as f64) / 3.0;
    if jaro <= 0.7 { return jaro; }
    let mut l = 0usize;
    for i in 0..usize::min(4, usize::min(l1, l2)) {
        if s1[i] != s2[i] { break; }
        l += 1;
    }
    jaro + l as f64 * 0.1 * (1.0 - jaro)
}
fn main() {
    for p in [("lenien","lenient"),("lenien","version"),("lenien","help"),("hepl","help"),("hel","help")] {
        println!("{:?} {:?} {}", p.0, p.1, jaro_winkler(p.0,p.1));
    }
}
