/// Parse the top level of an ABI spec: only a sequence is accepted; for any
/// other value serde reports "invalid type: <X>, expected valid abi spec file".
pub fn parse_top(s: &[u8]) -> Result<Node, JErr> {
    let mut r = Reader::new(s);
    r.skip_ws();
    match r.peek() {
        None => return Err(r.peek_err("EOF while parsing a value")),
        Some(b'[') => {
            let n = parse_value(&mut r)?;
            r.skip_ws();
            if r.i < s.len() {
                return Err(r.peek_err("trailing characters"));
            }
            return Ok(n);
        }
        Some(b'{') => {
            r.i += 1;
            r.skip_ws();
            let idx = if r.peek() == Some(b'}') { r.i + 1 } else { r.i };
            return Err(r.err_at("invalid type: map, expected valid abi spec file", idx));
        }
        Some(c) => {
            let n = parse_value(&mut r)?;
            let idx = if matches!(n.val, Val::Num(Num::U(_)) | Val::Num(Num::I(_)) | Val::Num(Num::F(_))) {
                usize::min(s.len(), n.end + 1)
            } else {
                n.end
            };
            let _ = c;
            return Err(r.err_at(
                &format!("invalid type: {}, expected valid abi spec file", unexpected_desc(&n)),
                idx,
            ));
        }
    }
}
